// ================= HYBRID & NANO-FINISHING PROCESSES =================
CATS.hyb={name:'Hybrid processes',sub:'Two energy sources acting together on the same zone',col:'--hyb'};
CATS.nano={name:'Nano-finishing',sub:'Surface finishing to nanometre-level roughness',col:'--nano'};
const MU0=4*Math.PI*1e-7;
PROCESSES.push(
/* ======================= ECG ======================= */
{id:'ecg',abbr:'ECG',name:'Electrochemical Grinding',cat:'hyb',
 blurb:'A conductive diamond wheel dissolves the work electrolytically; abrasive grains scrape off the passive film.',
 facts:{energy:'Electrochemical (≈90 %) + mechanical abrasion (≈10 %)',mech:'Anodic dissolution, with abrasion removing the oxide film',medium:'NaNO₃ / NaNO₂ electrolyte fed into the wheel gap',tool:'Metal-bonded diamond or Al₂O₃ wheel (cathode)'},
 aim:'To study how voltage, wheel–work gap and contact area govern current, MRR and the electrolytic share of removal in electrochemical grinding.',
 params:[
  {id:'V',label:'Applied voltage',unit:'V',min:4,max:16,step:0.5,val:6},
  {id:'g',label:'Gap (abrasive protrusion)',unit:'mm',min:0.01,max:0.08,step:0.005,val:0.025},
  {id:'A',label:'Wheel–work contact area',unit:'mm²',min:50,max:2000,step:10,val:400},
  {id:'k',label:'Electrolyte conductivity κ',unit:'S/m',min:5,max:25,step:0.5,val:15},
  {id:'vs',label:'Wheel surface speed',unit:'m/s',min:10,max:35,step:1,val:25},
  {id:'mat',label:'Work material',type:'select',val:'wc',options:[['wc','WC-Co carbide (WC → WO₄²⁻, 10 e⁻)'],['steel','Tool steel (Fe²⁺)'],['ni','Nickel superalloy (Ni²⁺)']]},
 ],
 mats:{wc:{M:195.85,z:10,rho:14.5,eta:0.85},steel:{M:55.85,z:2,rho:7.86,eta:0.9},ni:{M:58.69,z:2,rho:8.2,eta:0.85}},
 outputs:[{k:'mrr',label:'MRR',unit:'mm³/min',pri:1},{k:'I',label:'Current',unit:'A'},{k:'J',label:'Current density',unit:'A/cm²'},{k:'fe',label:'Electrolytic share',unit:'%'},{k:'feed',label:'Equivalent infeed',unit:'mm/min'},{k:'P',label:'Power',unit:'kW'}],
 sweep:{x:'V',y:'mrr'},
 compute(p){const m=this.mats[p.mat];const Ve=Math.max(p.V-1.5,0.1);const J=p.k*Ve/(p.g/1000);const I=J*p.A*1e-6;
  const mrrE=m.eta*I*(m.M/1000)/(m.z*FARADAY*m.rho*1000)*1e9*60;const fm=0.04*p.vs/10;const mrr=mrrE/(1-fm);
  const notes=[];if(J/1e4>300)notes.push('Current density above ~300 A/cm²: risk of sparking across the gap and wheel bond damage.');
  if(p.g<0.015)notes.push('Very small gap: abrasive grains barely protrude, so the passive film is not removed well and short circuits are likely.');
  return {o:{mrr,I,J:J/1e4,fe:(1-fm)*100,feed:mrr/p.A,P:I*p.V/1000},notes};},
 theory:{principle:['ECG looks like surface or cylindrical grinding, but the wheel is metal-bonded and connected as the cathode. Non-conductive abrasive grains protrude about 0.025 mm from the bond and set the gap, which is flooded with electrolyte.',
  'When voltage is applied, the work dissolves anodically just as in ECM. The dissolution forms a thin passive oxide film, and the grains scrape it away so dissolution can continue. About 90 % of the metal is removed electrochemically and about 10 % by abrasion.',
  'Because cutting forces and heat are very small, ECG gives burr-free, stress-free edges on hard carbides and thin sections, and the diamond wheel lasts far longer than in conventional grinding.'],
  eq:[{f:'<var>J</var> = κ(<var>V</var> − Δ<var>V</var>)/<var>g</var>,   <var>I</var> = <var>J</var>·<var>A</var>',w:'Current through the electrolyte-filled gap g over contact area A.'},
   {f:'MRR<sub>e</sub> = η<var>I</var><var>M</var>/(<var>z</var><var>F</var>ρ),   MRR = MRR<sub>e</sub>/(1 − <var>f</var><sub>m</sub>)',w:'Faraday dissolution plus a mechanical share f_m (≈10 %).'}],
  effects:['MRR rises linearly with voltage and inversely with gap.','A larger contact area raises current and MRR at the same infeed.','Wheel speed mainly helps electrolyte supply and film removal.','Carbide dissolution needs 10 electrons per WC unit, so its volumetric rate per ampere is lower than steel\'s.'],
  apps:['Sharpening and shaping carbide cutting tools','Burr-free grinding of honeycomb and thin-walled parts','Hypodermic needle points and surgical tools','Grinding fragile turbine components'],
  adv:['No burrs, no heat damage, minimal residual stress','Wheel wear is very low (high G-ratio)','Good finish on hard, tough conductive materials'],
  lim:['Only conductive work','Corrosive electrolyte; machine must be protected','Higher equipment cost than conventional grinding','Accuracy limited by stray dissolution at edges'],
  model:'<b>Simulator model.</b> ECM-style Faraday + Ohm model with ΔV = 1.5 V. Carbide is treated as WC oxidising to tungstate with 10 electrons per formula unit (cobalt binder ignored). The mechanical share f_m = 0.04·v_s/10 (≈10 % at 25 m/s) is an assumption matching the textbook 90/10 split. Not validated.'},
 procedure:['Select WC-Co work, gap 0.025 mm, contact area 400 mm².','Vary voltage from 4 to 16 V; record current and MRR.','Vary the gap from 0.01 to 0.08 mm at 8 V and record MRR.','Compare carbide with tool steel at the same current; explain using z and ρ.'],
 quiz:[{q:'In ECG, the larger share of material is removed by…',o:['Abrasion','Electrochemical dissolution','Melting','Erosion by electrolyte jets'],a:1,why:'About 90 % electrochemical, 10 % mechanical.'},
  {q:'The gap between wheel bond and work in ECG is set by…',o:['A servo gap sensor','Protruding non-conductive abrasive grains','Electrolyte pressure','Wheel speed'],a:1,why:'Grains protrude about 0.025 mm and act as spacers.'},
  {q:'A key advantage of ECG for carbide tools is…',o:['Very high MRR on soft metals','Burr-free, stress-free edges with little wheel wear','No electrolyte needed','Works on ceramics'],a:1,why:'Forces and heat are tiny compared with conventional grinding.'},
  {q:'In ECG the grinding wheel is connected as the…',o:['Anode','Cathode','Ground only','It is insulated'],a:1,why:'The work is the anode and dissolves.'}]},
/* ======================= ECDM ======================= */
{id:'ecdm',abbr:'ECDM',name:'Electrochemical Discharge Machining',cat:'hyb',
 blurb:'Sparks through a gas film around a tool in alkaline electrolyte drill holes in glass and quartz.',
 facts:{energy:'Electrochemical + electrothermal discharges',mech:'Thermal melting by discharges plus chemical etching by hot NaOH',medium:'NaOH or KOH solution, 10–40 wt %',tool:'Thin tool cathode; large counter-electrode anode'},
 aim:'To study the critical voltage for discharge, and how voltage, electrolyte concentration and time affect drilling depth in glass by ECDM.',
 params:[
  {id:'V',label:'Applied voltage',unit:'V',min:15,max:60,step:0.5,val:40},
  {id:'c',label:'NaOH concentration',unit:'wt %',min:10,max:40,step:1,val:30},
  {id:'d',label:'Tool diameter',unit:'mm',min:0.2,max:1.0,step:0.05,val:0.5},
  {id:'t',label:'Machining time',unit:'s',min:10,max:300,step:5,val:60},
  {id:'mat',label:'Work material',type:'select',val:'glass',options:[['glass','Soda-lime glass'],['quartz','Fused quartz'],['alumina','Alumina ceramic']]},
 ],
 mats:{glass:1.0,quartz:0.55,alumina:0.35},
 outputs:[{k:'h',label:'Hole depth',unit:'µm',pri:1},{k:'Vc',label:'Critical voltage',unit:'V'},{k:'r0',label:'Initial drilling rate',unit:'µm/s'},{k:'ravg',label:'Average rate',unit:'µm/s'},{k:'De',label:'Entrance diameter',unit:'mm'}],
 sweep:{x:'V',y:'h'},
 compute(p){const Vc=26-0.15*(p.c-20);const dv=p.V-Vc;const notes=[];
  if(dv<=0){notes.push(`Below the critical voltage (${Vc.toFixed(1)} V): only electrolysis and bubble formation occur; no discharges, so no machining.`);return {o:{h:0,Vc,r0:0,ravg:0,De:p.d},notes};}
  const r0=4.5*Math.pow(dv/10,1.5)*Math.sqrt(p.c/30)*this.mats[p.mat];const h0=250*Math.sqrt(p.d/0.5);const h=h0*Math.log(1+r0*p.t/h0);const oc=0.05+0.004*dv;
  if(dv>25)notes.push('High voltage above critical: discharges become violent, causing wide entrance, heat-affected zone and micro-cracks.');
  if(h>2*h0)notes.push('Drilling rate has fallen sharply with depth: fresh electrolyte cannot reach the tool tip (gravity-feed limitation).');
  return {o:{h,Vc,r0,ravg:h/p.t,De:p.d+2*oc},notes};},
 theory:{principle:['The tool (cathode) and a much larger counter-electrode (anode) are dipped in strong alkaline electrolyte. As voltage rises, hydrogen bubbles at the tool coalesce into a continuous gas film that insulates the tool.',
  'Above a critical voltage (about 25–30 V), the field across this film breaks it down and electrical discharges occur between tool and electrolyte. Each discharge heats the nearby glass; hot NaOH then etches the softened glass.',
  'ECDM machines non-conductive, brittle materials such as glass and quartz for micro-fluidic channels and holes. Depth rate is high at first and falls sharply as the hole deepens because electrolyte cannot reach the tip.'],
  eq:[{f:'Machining only when <var>V</var> > <var>V</var><sub>c</sub>',w:'V_c ≈ 25–30 V, falling with electrolyte concentration.'},
   {f:'d<var>h</var>/d<var>t</var> = <var>r</var><sub>0</sub>·e<sup>−h/h₀</sup>  ⇒  <var>h</var>(<var>t</var>) = <var>h</var><sub>0</sub> ln(1 + <var>r</var><sub>0</sub><var>t</var>/<var>h</var><sub>0</sub>)',w:'Empirical depth law: initial rate r₀ grows with (V − V_c)^1.5; h₀ reflects electrolyte starvation at depth.'}],
  effects:['No removal below the critical voltage.','Depth rises steeply with voltage above critical, but so do overcut and cracking.','Higher NaOH concentration lowers V_c and speeds etching.','Depth grows only logarithmically with time in gravity-feed drilling.'],
  apps:['Micro-holes and channels in glass for micro-fluidics and MEMS','Through-glass vias','Quartz and borosilicate components','Drilling of ceramics for sensors'],
  adv:['Machines non-conductive brittle materials','Simple, low-cost set-up','No tool wear by contact forces'],
  lim:['Low depth (typically < 1 mm by gravity feed)','Heat-affected zone and micro-cracks at high voltage','Overcut and tapered holes','Corrosive hot electrolyte'],
  model:'<b>Simulator model.</b> V_c = 26 − 0.15·(c − 20) V. r₀ = 4.5·((V − V_c)/10)^1.5·√(c/30)·k_mat µm/s, h₀ = 250·√(d/0.5) µm. These reproduce typical trends from the ECDM literature (≈300 µm in 60 s at 40 V in glass) but are indicative and not validated.'},
 procedure:['Select glass, 30 % NaOH, 0.5 mm tool.','Increase voltage from 20 V in 2 V steps and find the voltage at which depth first becomes non-zero (critical voltage).','At 40 V, vary time from 10 to 300 s and plot depth vs time.','Repeat at 20 % concentration and compare the critical voltage.'],
 quiz:[{q:'ECDM is mainly used to machine…',o:['Hardened steel','Glass and other non-conductive brittle materials','Aluminium sheet','Titanium'],a:1,why:'The work need not conduct; discharges occur in the gas film around the tool.'},
  {q:'Below the critical voltage in ECDM…',o:['Material removal is maximum','Only electrolysis occurs; no discharges','The tool melts','The work becomes conductive'],a:1,why:'A stable gas film and its breakdown need a minimum voltage.'},
  {q:'The insulating layer that breaks down to produce discharges is…',o:['An oxide film on the work','A hydrogen gas film around the tool','The glass itself','A polymer coating'],a:1,why:'Hydrogen bubbles coalesce into a film around the cathode.'},
  {q:'Why does drilling rate fall with depth in gravity-feed ECDM?',o:['The tool wears','Fresh electrolyte cannot reach the tool tip','Voltage drops','The glass hardens'],a:1,why:'Electrolyte starvation and debris at the hole bottom limit discharges and etching.'}]},
/* ======================= RUM ======================= */
{id:'rum',abbr:'RUM',name:'Rotary Ultrasonic Machining',cat:'hyb',
 blurb:'A rotating diamond core drill vibrating ultrasonically cuts hard ceramics with lower force and less chipping.',
 facts:{energy:'Mechanical: diamond grinding + ultrasonic vibration',mech:'Grinding plus brittle micro-fracture from hammering grains',medium:'Coolant pumped through the hollow tool',tool:'Metal-bonded diamond core drill'},
 aim:'To compare rotary ultrasonic machining with conventional diamond drilling, and study how feed rate, spindle speed and amplitude affect cutting force and MRR.',
 params:[
  {id:'f',label:'Feed rate',unit:'mm/min',min:0.2,max:5,step:0.1,val:1.5},
  {id:'N',label:'Spindle speed',unit:'rpm',min:1000,max:6000,step:100,val:3000},
  {id:'A0',label:'Ultrasonic amplitude (0 = conventional)',unit:'µm',min:0,max:40,step:1,val:20},
  {id:'D',label:'Tool outer diameter',unit:'mm',min:6,max:16,step:0.5,val:10},
  {id:'w',label:'Tool wall thickness',unit:'mm',min:0.8,max:2,step:0.1,val:1.2},
  {id:'mat',label:'Work material',type:'select',val:'alumina',options:[['glass','Optical glass'],['alumina','Alumina ceramic'],['sic','Silicon carbide']]},
 ],
 K:{glass:60,alumina:154,sic:200},
 outputs:[{k:'F',label:'Axial cutting force',unit:'N',pri:1},{k:'mrr',label:'MRR',unit:'mm³/min'},{k:'red',label:'Force reduction vs conventional',unit:'%'},{k:'Ra',label:'Surface roughness Ra (est.)',unit:'µm'},{k:'chip',label:'Exit chipping size (est.)',unit:'mm'}],
 sweep:{x:'f',y:'F'},
 compute(p){const K=this.K[p.mat];const s=Math.pow(p.N/3000,-0.3)*(p.D/10);const F=K*Math.pow(p.f,0.6)*s*Math.pow(1+p.A0/10,-0.45);const F0=K*Math.pow(p.f,0.6)*s;
  const mrr=p.f*Math.PI/4*(p.D*p.D-Math.pow(p.D-2*p.w,2));const notes=[];
  if(p.A0===0)notes.push('Amplitude 0: this is conventional diamond core drilling, for comparison.');
  if(F>250)notes.push('High axial force: expect large edge chipping at hole exit and risk of tool breakage.');
  return {o:{F,mrr,red:(1-F/F0)*100,Ra:(0.35+0.3*Math.pow(p.f,0.4))*(p.A0>0?0.85:1),chip:0.004*F},notes};},
 theory:{principle:['RUM combines diamond grinding and ultrasonic machining. A metal-bonded diamond core drill rotates while a transducer vibrates it axially at about 20 kHz with an amplitude of 5–40 µm. Coolant is pumped through the hollow tool.',
  'Unlike conventional USM there is no loose abrasive slurry; the diamond grains are bonded to the tool. The vibration makes grains repeatedly impact and lift off, so chips are cleared and coolant reaches the cutting zone.',
  'Compared with conventional diamond drilling, RUM lowers cutting force, tool wear and edge chipping, and allows higher feed rates in hard, brittle ceramics and composites.'],
  eq:[{f:'MRR = <var>f</var> · π/4 · (<var>D</var><sup>2</sup> − <var>d</var><sub>i</sub><sup>2</sup>)',w:'Feed-controlled removal by a core drill.'},
   {f:'<var>F</var> = <var>K</var> · <var>f</var><sup>0.6</sup> · <var>N</var><sup>−0.3</sup> · (1 + <var>A</var><sub>0</sub>/10)<sup>−0.45</sup>',w:'Empirical trend: force rises with feed and falls with spindle speed and amplitude.'}],
  effects:['Cutting force rises with feed rate, roughly as f^0.6.','Higher spindle speed lowers force.','Ultrasonic vibration lowers force by about 30–45 % at typical amplitudes.','Lower force means smaller exit chipping.'],
  apps:['Holes in alumina, SiC, zirconia and glass','Drilling of CFRP and ceramic-matrix composites','Optical glass and sapphire components','Hard and brittle aerospace materials'],
  adv:['Lower force and less chipping than conventional drilling','Higher MRR than conventional USM','Good hole quality in brittle materials'],
  lim:['Needs special ultrasonic spindle','Mainly holes and simple shapes with core tools','Diamond tools are costly'],
  model:'<b>Simulator model.</b> MRR is exact for a core drill. The force law is an empirical trend with K = 60 / 154 / 200 for glass / alumina / SiC, calibrated to about 120 N for alumina at 1.5 mm/min, 3000 rpm and 20 µm. The exponents follow trends reported in RUM literature (e.g. Pei et al.). Ra and chipping are indicative. Not validated.'},
 procedure:['Select alumina, 10 mm tool, 3000 rpm.','Set amplitude to 0 (conventional) and vary feed from 0.5 to 4 mm/min; hold the curve.','Set amplitude to 20 µm and repeat; compare the two curves.','Vary spindle speed at fixed feed and record force.'],
 quiz:[{q:'RUM differs from conventional USM because…',o:['It uses loose slurry','Abrasive diamond is bonded to a rotating tool','It needs a conductive work','It uses no vibration'],a:1,why:'RUM uses a bonded-diamond rotating tool plus vibration.'},
  {q:'Adding ultrasonic vibration to diamond core drilling mainly…',o:['Raises cutting force','Lowers cutting force and edge chipping','Melts the work','Removes the need for coolant'],a:1,why:'Intermittent contact and better chip clearance reduce force.'},
  {q:'MRR of a core drill at feed f equals…',o:['f × π D²/4','f × π (D² − d_i²)/4','f × D','π D N'],a:1,why:'Only the annulus is removed; the core remains.'},
  {q:'Coolant in RUM is usually supplied…',o:['Not at all','Through the hollow core tool','By mist only','In a tank of oil'],a:1,why:'Through-tool coolant flushes debris from the annular cut.'}]},
/* ======================= LAM ======================= */
{id:'lam',abbr:'LAM',name:'Laser-Assisted Machining',cat:'hyb',
 blurb:'A laser heats the material just ahead of the cutting tool, softening hard alloys and ceramics.',
 facts:{energy:'Thermal (laser) + mechanical (turning)',mech:'Thermal softening ahead of a conventional cutting edge',medium:'Air; laser spot just ahead of the tool',tool:'Carbide, CBN or PCBN insert + CO₂/fiber/diode laser'},
 aim:'To study how laser power and cutting speed affect the material temperature at the cutting zone and the resulting cutting force in laser-assisted turning.',
 params:[
  {id:'P',label:'Laser power',unit:'W',min:0,max:2000,step:50,val:1000},
  {id:'v',label:'Cutting speed',unit:'m/min',min:20,max:200,step:5,val:60},
  {id:'f',label:'Feed',unit:'mm/rev',min:0.05,max:0.3,step:0.01,val:0.1},
  {id:'ap',label:'Depth of cut',unit:'mm',min:0.2,max:2,step:0.1,val:0.5},
  {id:'d',label:'Laser spot diameter',unit:'mm',min:1,max:4,step:0.1,val:2},
  {id:'mat',label:'Work material',type:'select',val:'inco',options:[['inco','Inconel 718'],['ti','Ti-6Al-4V'],['si3n4','Silicon nitride']]},
 ],
 mats:{inco:{k:11.4,a:3.1e-6,u0:4.5,Tm:1609,m:1.3,eta:0.35},ti:{k:6.7,a:2.9e-6,u0:4.0,Tm:1933,m:0.8,eta:0.35},si3n4:{k:30,a:1.2e-5,u0:10,Tm:2173,m:2.0,eta:0.6}},
 outputs:[{k:'T',label:'Cutting-zone temperature',unit:'°C',pri:1},{k:'Fc',label:'Cutting force',unit:'N'},{k:'red',label:'Force reduction vs no laser',unit:'%'},{k:'Pc',label:'Cutting power',unit:'W'},{k:'u',label:'Specific cutting energy',unit:'J/mm³'}],
 sweep:{x:'P',y:'Fc'},
 compute(p){const m=this.mats[p.mat];const d=p.d/1000,v=p.v/60;const q=m.eta*p.P/(d*d),l=d/2;
  const dT=0.754*q*l/m.k*Math.sqrt(2*m.a/(v*d));const T=25+dT;const Ts=Math.min(0.95,Math.max(0,(T-25)/(m.Tm-298)));const u=m.u0*(1-Math.pow(Ts,m.m));
  const Fc=u*1000*p.f*p.ap,F0=m.u0*1000*p.f*p.ap;const notes=[];
  if(p.mat==='si3n4'&&T<1000)notes.push('Silicon nitride needs roughly 1000–1400 °C at the cutting zone to machine in a ductile mode. Below that it chips and destroys the tool.');
  if(Ts>0.8)notes.push('Temperature close to melting: risk of surface damage and changed microstructure.');
  return {o:{T,Fc,red:(1-Fc/F0)*100,Pc:Fc*v,u},notes};},
 theory:{principle:['In laser-assisted machining, a laser beam heats a spot on the workpiece just ahead of the cutting tool. By the time the heated material reaches the tool it is hotter, softer and, for ceramics, more ductile.',
  'The heat must soften the layer being cut without overheating the tool or damaging the finished surface. Power, spot size, cutting speed and the lead distance between spot and tool are chosen together.',
  'LAM lowers cutting forces and tool wear on nickel superalloys, titanium and hardened steel, and makes it possible to turn silicon nitride and zirconia with a single-point tool.'],
  eq:[{f:'Δ<var>T</var> ≈ 0.754 · (<var>q</var>·<var>l</var>/<var>k</var>) · √(2α/(<var>v</var>·<var>d</var>))',w:'Jaeger fast-moving heat source: absorbed flux q over half-width l, conductivity k, diffusivity α, speed v.'},
   {f:'<var>u</var>(<var>T</var>) = <var>u</var><sub>0</sub> [1 − <var>T</var>*<sup>m</sup>],   <var>F</var><sub>c</sub> = <var>u</var>·<var>f</var>·<var>a</var><sub>p</sub>  (1 J/mm³ = 1000 N/mm²)',w:'Johnson–Cook-type thermal softening of specific cutting energy; T* = homologous temperature.'}],
  effects:['Higher laser power raises cutting-zone temperature and lowers force.','Higher cutting speed leaves less time for heating, so temperature falls.','Low conductivity (Ti, Inconel) concentrates heat and helps LAM.','Ceramics need much higher temperatures than metals.'],
  apps:['Turning Inconel and titanium aerospace parts','Machining Si₃N₄ and zirconia components','Hardened steel turning','Hybrid repair of additive-manufactured parts'],
  adv:['Lower forces and longer tool life on difficult materials','Machines ceramics with single-point tools','Higher MRR than grinding for ceramics'],
  lim:['Expensive laser and safety enclosure','Risk of surface heat damage','Process window is narrow and material-specific'],
  model:'<b>Simulator model.</b> Average temperature from Jaeger\'s fast-moving band-source solution, with absorptivity 0.35 for metals and 0.6 for Si₃N₄. Specific cutting energy u₀ = 4.5 / 4.0 / 10 J/mm³ for Inconel / Ti-6Al-4V / Si₃N₄, softened as 1 − T*^m. This is a simplified average-temperature model; real LAM needs lead distance and transient heating. Indicative only, not validated.'},
 procedure:['Select Inconel 718, 60 m/min, f = 0.1 mm/rev, a_p = 0.5 mm.','Vary laser power from 0 to 2000 W; record temperature and cutting force.','At 1000 W, vary cutting speed from 20 to 200 m/min.','Compare Inconel with Ti-6Al-4V and explain using thermal conductivity.'],
 quiz:[{q:'In LAM the laser is aimed…',o:['At the tool rake face','At the workpiece just ahead of the tool','At the chip after cutting','At the machined surface behind the tool'],a:1,why:'It preheats material that is about to be cut.'},
  {q:'Increasing cutting speed at fixed laser power…',o:['Raises cutting-zone temperature','Lowers cutting-zone temperature','Has no effect','Melts the tool'],a:1,why:'Less interaction time means less heat per unit volume.'},
  {q:'LAM is especially attractive for silicon nitride because…',o:['It is conductive','Heating makes it deform plastically instead of fracturing','It is soft at room temperature','It absorbs no laser light'],a:1,why:'Above ~1000 °C the glassy grain-boundary phase softens.'},
  {q:'A main risk in LAM is…',o:['Too much tool wear from cold cutting','Heat damage to the finished surface','Electrolyte corrosion','Abrasive contamination'],a:1,why:'Overheating can alter the microstructure of the machined layer.'}]},
/* ======================= AFM ======================= */
{id:'afm',abbr:'AFM',name:'Abrasive Flow Machining',cat:'nano',
 blurb:'Abrasive-laden viscoelastic putty is extruded back and forth through a passage to deburr and polish it.',
 facts:{energy:'Mechanical (pressure-driven flow of abrasive media)',mech:'Micro-cutting by abrasive grains held in a viscoelastic carrier',medium:'Polymer putty + SiC / Al₂O₃ / B₄C / diamond abrasive',tool:'The media itself; fixture directs the flow'},
 aim:'To study how extrusion pressure, abrasive concentration, grit size and number of cycles reduce surface roughness in abrasive flow machining.',
 params:[
  {id:'p',label:'Extrusion pressure',unit:'MPa',min:2,max:10,step:0.5,val:6},
  {id:'C',label:'Abrasive concentration',unit:'wt %',min:20,max:65,step:1,val:45},
  {id:'dg',label:'Abrasive grit size',unit:'µm',min:10,max:200,step:5,val:60},
  {id:'n',label:'Number of cycles',unit:'',min:1,max:100,step:1,val:20},
  {id:'Ra0',label:'Initial roughness Ra₀',unit:'µm',min:0.5,max:5,step:0.1,val:2},
  {id:'mat',label:'Work material',type:'select',val:'steel',options:[['al','Aluminium alloy'],['steel','Mild steel'],['hard','Hardened steel']]},
 ],
 H:{al:0.8,steel:2,hard:6.5},
 outputs:[{k:'Ra',label:'Final Ra',unit:'µm',pri:1},{k:'imp',label:'Improvement in Ra',unit:'%'},{k:'Rmin',label:'Limiting Ra (this grit)',unit:'µm'},{k:'n0',label:'Characteristic cycles n₀',unit:''},{k:'n90',label:'Cycles to 90 % of possible gain',unit:''}],
 sweep:{x:'n',y:'Ra'},
 compute(p){const Rmin=Math.min(p.Ra0*0.9,0.004*p.dg);const n0=25*(6/p.p)*(45/p.C)*Math.sqrt(this.H[p.mat]/2);const Ra=Rmin+(p.Ra0-Rmin)*Math.exp(-p.n/n0);
  const notes=[];if(p.C>60)notes.push('Very high abrasive concentration makes the media stiff and hard to extrude.');if(Rmin>0.5)notes.push('Coarse grit limits the finish. Use finer grit for the final passes.');
  return {o:{Ra,imp:(1-Ra/p.Ra0)*100,Rmin,n0,n90:n0*Math.log(10)},notes};},
 theory:{principle:['The workpiece is clamped in a fixture between two vertically opposed media cylinders. Pistons push a viscoelastic polymer media loaded with abrasive back and forth through the passages to be finished.',
  'Where the passage narrows, the media thickens and presses the abrasive against the walls. The grains then shear off the roughness peaks. Edges are radiused and burrs removed, even inside intersecting holes.',
  'Roughness falls quickly in the first cycles and then levels off at a limit set mainly by grit size. Pressure, concentration and media viscosity control how fast that limit is approached.'],
  eq:[{f:'<var>R</var><sub>a</sub>(<var>n</var>) = <var>R</var><sub>a,min</sub> + (<var>R</var><sub>a0</sub> − <var>R</var><sub>a,min</sub>)·e<sup>−n/n₀</sup>',w:'Exponential approach to a limiting roughness set by grit size.'},
   {f:'<var>n</var><sub>0</sub> ∝ (1/<var>p</var>)·(1/<var>C</var>)·√<var>H</var>',w:'Higher pressure and concentration finish faster; harder work finishes slower.'}],
  effects:['Most improvement happens in the first few tens of cycles.','Higher extrusion pressure and abrasive concentration speed finishing.','Finer grit gives a lower limiting roughness but slower removal.','Harder workpieces need more cycles.'],
  apps:['Deburring intersecting holes in hydraulic and fuel-system parts','Polishing turbine blades, impellers and dies','Finishing internal passages of additively manufactured parts','Medical implants'],
  adv:['Reaches internal, complex passages','Uniform, repeatable finish; many parts at once','Removes burrs and recast layers'],
  lim:['Low material removal; not for shape changes','Media cost and contamination','Fixture design needed for each part'],
  model:'<b>Simulator model.</b> Exponential roughness decay with Ra_min = 0.004·grit size and n₀ = 25·(6/p)·(45/C)·√(H/2). The trend is widely reported (e.g. Jain & Jain), but these constants are indicative and not validated.'},
 procedure:['Select mild steel, Ra₀ = 2 µm, grit 60 µm.','Vary cycles from 1 to 100 at 6 MPa; plot Ra vs cycles.','Hold the curve and repeat at 3 MPa and 10 MPa.','Change grit size to 20 µm and compare limiting Ra.'],
 quiz:[{q:'In AFM the "tool" is…',o:['A grinding wheel','Abrasive-laden viscoelastic media','A laser beam','An electrode'],a:1,why:'The media carries the abrasive through the passage.'},
  {q:'With more AFM cycles, surface roughness…',o:['Falls linearly forever','Falls quickly then levels off','Rises','Does not change'],a:1,why:'It approaches a limit set mainly by grit size.'},
  {q:'A major application of AFM is…',o:['Cutting thick plate','Deburring and polishing internal passages','Drilling glass','Welding'],a:1,why:'The media follows internal geometry that tools cannot reach.'},
  {q:'Increasing extrusion pressure in AFM…',o:['Slows finishing','Speeds up finishing','Has no effect','Stops the flow'],a:1,why:'Grains are pressed harder against the surface.'}]},
/* ======================= MAF ======================= */
{id:'maf',abbr:'MAF',name:'Magnetic Abrasive Finishing',cat:'nano',
 blurb:'A magnetic field holds iron–abrasive particles as a flexible brush that polishes the rotating work.',
 facts:{energy:'Magnetic field + mechanical rotation',mech:'Micro-cutting by abrasive held in a magnetic brush',medium:'Magnetic abrasive (iron + Al₂O₃/SiC/diamond) with lubricant',tool:'Flexible magnetic abrasive brush between magnetic poles'},
 aim:'To study how magnetic flux density, rotation speed and finishing time reduce surface roughness in magnetic abrasive finishing of cylindrical work.',
 params:[
  {id:'B',label:'Flux density in gap',unit:'T',min:0.1,max:1.2,step:0.05,val:0.6},
  {id:'N',label:'Work rotation',unit:'rpm',min:200,max:2000,step:50,val:800},
  {id:'t',label:'Finishing time',unit:'min',min:1,max:30,step:1,val:10},
  {id:'da',label:'Abrasive particle size',unit:'µm',min:50,max:400,step:10,val:150},
  {id:'Ra0',label:'Initial roughness Ra₀',unit:'µm',min:0.2,max:2,step:0.05,val:0.8},
  {id:'mur',label:'Relative permeability of brush',unit:'',min:1.5,max:6,step:0.1,val:3},
 ],
 outputs:[{k:'Pm',label:'Magnetic finishing pressure',unit:'kPa',pri:1},{k:'Ra',label:'Final Ra',unit:'µm'},{k:'imp',label:'Improvement',unit:'%'},{k:'vs',label:'Surface speed',unit:'m/s'},{k:'tau',label:'Time constant',unit:'min'}],
 sweep:{x:'B',y:'Pm'},
 compute(p){const Pm=p.B*p.B/(2*MU0)*(1-1/p.mur);const vs=Math.PI*0.02*p.N/60;const tau=5*(95500/Pm)*(0.838/vs);const Rmin=Math.min(p.Ra0*0.9,0.0003*p.da);const Ra=Rmin+(p.Ra0-Rmin)*Math.exp(-p.t/tau);
  const notes=[];if(p.B<0.2)notes.push('Weak field: the brush is loose and finishing pressure is too low to cut.');if(p.B>1.0)notes.push('Near saturation of the iron particles; extra field gives little extra pressure in practice.');
  return {o:{Pm:Pm/1000,Ra,imp:(1-Ra/p.Ra0)*100,vs,tau},notes};},
 theory:{principle:['Magnetic abrasive particles, made of iron with fine abrasive embedded or mixed in, are placed in the gap between a magnetic pole and the workpiece. The field lines chain the particles into a flexible "brush".',
  'The field pulls the brush against the surface with a finishing pressure that depends on flux density. Rotating or vibrating the work makes the abrasive shear off peaks, giving nanometre-level finishes.',
  'Because the brush conforms to the surface, MAF can finish curved and internal surfaces, such as the inside of tubes, without rigid tools.'],
  eq:[{f:'<var>P</var><sub>m</sub> = (<var>B</var><sup>2</sup>/2μ<sub>0</sub>) · (1 − 1/μ<sub>r</sub>)',w:'Magnetic pressure on the brush (Shinmura): flux density B, brush relative permeability μ_r.'},
   {f:'<var>R</var><sub>a</sub>(<var>t</var>) = <var>R</var><sub>a,min</sub> + (<var>R</var><sub>a0</sub> − <var>R</var><sub>a,min</sub>)·e<sup>−t/τ</sup>,   τ ∝ 1/(<var>P</var><sub>m</sub>·<var>v</var>)',w:'Exponential finishing following a Preston-type rate.'}],
  effects:['Finishing pressure rises with the square of flux density.','Higher rotation speed shortens finishing time.','Finer abrasive gives a lower final Ra.','Roughness levels off after a few time constants.'],
  apps:['Inner surfaces of tubes for semiconductor gas lines and medical tubing','Bearing races and shafts','Deburring of small precision parts','Finishing of freeform surfaces'],
  adv:['Nanometre-level finish with low force','Self-adapting flexible brush','No heat damage'],
  lim:['Low MRR','Works best on simple geometries or with custom poles','Magnetic abrasive wears and must be replaced'],
  model:'<b>Simulator model.</b> Magnetic pressure from Shinmura\'s expression. Finishing time constant τ = 5 min at 95.5 kPa and 0.84 m/s (20 mm work at 800 rpm), scaling inversely with pressure × speed. Ra_min = 0.0003 × particle size. The pressure formula is standard; the finishing constants are indicative and not validated.'},
 procedure:['Set B = 0.6 T, 800 rpm, 150 µm particles, Ra₀ = 0.8 µm.','Vary B from 0.1 to 1.2 T and record finishing pressure.','At 0.6 T, vary time from 1 to 30 min and plot Ra vs time.','Repeat at 400 and 1600 rpm and compare.'],
 quiz:[{q:'In MAF the finishing pressure comes from…',o:['A hydraulic cylinder','The magnetic field acting on iron particles','Gravity','Centrifugal force'],a:1,why:'The field pulls the magnetic brush against the work.'},
  {q:'Doubling the flux density B multiplies the magnetic pressure by about…',o:['2','4','√2','1'],a:1,why:'P ∝ B².'},
  {q:'A key strength of MAF is…',o:['Very high MRR','A flexible brush that follows curved and internal surfaces','Cutting thick plate','Drilling holes'],a:1,why:'The brush adapts to surface shape.'},
  {q:'Typical final roughness achievable by MAF is in the range of…',o:['10–50 µm','1–5 µm','Tens of nanometres','Millimetres'],a:2,why:'MAF is a nano-finishing process.'}]},
/* ======================= MRF ======================= */
{id:'mrf',abbr:'MRF',name:'Magnetorheological Finishing',cat:'nano',
 blurb:'A ribbon of MR fluid stiffened by a magnetic field polishes optics to nanometre form and finish.',
 facts:{energy:'Magnetic field + hydrodynamic shear',mech:'Shear removal by abrasive in a field-stiffened MR fluid ribbon (Preston law)',medium:'MR fluid: carbonyl iron + CeO₂ or diamond abrasive in water',tool:'Rotating wheel carrying the MR ribbon over an electromagnet'},
 aim:'To verify Preston\'s law in magnetorheological finishing: study how field strength, wheel speed and penetration depth set the removal rate on optical materials.',
 params:[
  {id:'B',label:'Magnetic flux density',unit:'T',min:0.1,max:0.8,step:0.05,val:0.4},
  {id:'v',label:'Wheel surface speed',unit:'m/s',min:0.5,max:3,step:0.1,val:1.5},
  {id:'dp',label:'Penetration depth into ribbon',unit:'mm',min:0.1,max:0.5,step:0.02,val:0.3},
  {id:'t',label:'Dwell time on spot',unit:'min',min:0.5,max:10,step:0.5,val:2},
  {id:'mat',label:'Work material',type:'select',val:'bk7',options:[['bk7','BK7 optical glass'],['fs','Fused silica'],['si','Silicon'],['sap','Sapphire']]},
 ],
 Cp:{bk7:5e-13,fs:2.5e-13,si:2e-13,sap:2e-14},
 outputs:[{k:'rr',label:'Removal rate',unit:'µm/min',pri:1},{k:'P',label:'Polishing pressure',unit:'kPa'},{k:'h',label:'Depth removed',unit:'µm'},{k:'Cp',label:'Preston coefficient',unit:'×10⁻¹³ m²/N'}],
 sweep:{x:'v',y:'rr'},
 compute(p){const P=20000*Math.pow(p.B/0.4,1.5)*(p.dp/0.3);const Cp=this.Cp[p.mat];const rr=Cp*P*p.v*60*1e6;
  const notes=[];if(p.B<0.15)notes.push('Field too weak: the fluid does not stiffen into a ribbon, so there is little polishing pressure.');
  return {o:{rr,P:P/1000,h:rr*p.t,Cp:Cp*1e13},notes};},
 theory:{principle:['MR fluid contains micron-sized carbonyl iron particles and fine polishing abrasive in water. Outside a magnetic field it flows like a liquid; inside a field its viscosity rises by orders of magnitude within milliseconds.',
  'A rotating wheel carries a thin ribbon of fluid through the field of an electromagnet. Where the workpiece dips into the stiffened ribbon, a small polishing spot forms, and the abrasive shears material away.',
  'Removal follows Preston\'s law. Because the spot is small and stable, computer control of dwell time over the surface corrects form errors to nanometres. MRF is used for precision lenses, mirrors and wafers.'],
  eq:[{f:'d<var>h</var>/d<var>t</var> = <var>C</var><sub>p</sub> · <var>P</var> · <var>v</var>',w:'Preston\'s equation: removal rate is proportional to pressure and relative velocity; C_p depends on material and slurry.'},
   {f:'<var>P</var> ≈ 20 kPa · (<var>B</var>/0.4 T)<sup>1.5</sup> · (δ/0.3 mm)',w:'Pressure rises with field (yield stress of MR fluid) and penetration depth δ (assumed scaling).'}],
  effects:['Removal rate rises linearly with wheel speed.','A stronger field stiffens the ribbon and raises pressure.','Deeper penetration raises pressure and enlarges the spot.','Harder materials (sapphire) polish far more slowly.'],
  apps:['Final figuring of precision lenses and aspheres','Telescope and laser mirrors','Silicon and SiC optics','Removing subsurface damage left by grinding'],
  adv:['Nanometre form accuracy under computer control','No subsurface damage; stable, predictable removal','Conforms to curved and aspheric surfaces'],
  lim:['Expensive equipment and fluid management','Low removal: a finishing, not shaping, process','Fluid properties must be held constant'],
  model:'<b>Simulator model.</b> Preston\'s law with C_p = 5, 2.5, 2 and 0.2 ×10⁻¹³ m²/N for BK7, fused silica, Si and sapphire, and an assumed pressure scaling with field and penetration depth. Gives about 1 µm/min on BK7 at default settings, a typical order of magnitude. Indicative, not validated.'},
 procedure:['Select BK7, B = 0.4 T, penetration 0.3 mm.','Vary wheel speed from 0.5 to 3 m/s and confirm removal rate ∝ speed.','At 1.5 m/s, vary field from 0.1 to 0.8 T.','Compare BK7 with sapphire and explain using the Preston coefficient.'],
 quiz:[{q:'MR fluid becomes stiff when…',o:['Heated','Placed in a magnetic field','Mixed with water','Exposed to light'],a:1,why:'Iron particles align into chains along field lines.'},
  {q:'Preston\'s law states that removal rate is proportional to…',o:['Pressure only','Pressure × relative velocity','Velocity squared','Temperature'],a:1,why:'dh/dt = C_p · P · v.'},
  {q:'MRF is mainly used for…',o:['Cutting thick metal','Final figuring and polishing of precision optics','Drilling holes','Welding'],a:1,why:'It corrects form to nanometres with no subsurface damage.'},
  {q:'Doubling wheel speed in MRF (all else equal) makes removal rate…',o:['Halve','Double','Stay the same','Quadruple'],a:1,why:'Linear in velocity by Preston\'s law.'}]},
/* ======================= CMP ======================= */
{id:'cmp',abbr:'CMP',name:'Chemical Mechanical Polishing',cat:'nano',
 blurb:'Slurry chemistry softens the surface while abrasive and pad pressure polish wafers flat to the nanometre.',
 facts:{energy:'Chemical + mechanical',mech:'Chemically softened surface layer removed by abrasive and pad',medium:'Slurry: colloidal silica / ceria / alumina + chemistry (pH, oxidiser)',tool:'Polyurethane pad on a rotating platen; wafer carrier'},
 aim:'To verify Preston\'s law in CMP and estimate polishing time to remove a film, for oxide, copper, tungsten and silicon.',
 params:[
  {id:'P',label:'Down pressure',unit:'kPa',min:7,max:55,step:1,val:34},
  {id:'v',label:'Relative velocity',unit:'m/s',min:0.3,max:2,step:0.05,val:1},
  {id:'h',label:'Film thickness to remove',unit:'nm',min:50,max:2000,step:10,val:500},
  {id:'mat',label:'Film / slurry',type:'select',val:'ox',options:[['ox','SiO₂ / silica slurry'],['cu','Copper / oxidiser + alumina'],['w','Tungsten / ferric nitrate + alumina'],['si','Silicon / alkaline silica']]},
 ],
 Cp:{ox:9.8e-14,cu:6e-13,w:1.5e-13,si:1.2e-13},
 outputs:[{k:'rr',label:'Removal rate',unit:'nm/min',pri:1},{k:'tclr',label:'Time to clear film',unit:'s'},{k:'psi',label:'Pressure',unit:'psi'},{k:'Cp',label:'Preston coefficient',unit:'×10⁻¹³ m²/N'}],
 sweep:{x:'P',y:'rr'},
 compute(p){const Cp=this.Cp[p.mat];const P0=34,v0=1,Pth=7;const ref=Cp*P0*1000*v0;let rrs;
  if(p.model==='tw')rrs=ref*Math.pow(p.P/P0,5/6)*Math.pow(p.v/v0,0.5);else if(p.model==='zs')rrs=ref*Math.max(0,Math.pow(p.P,2/3)-Math.pow(Pth,2/3))/(Math.pow(P0,2/3)-Math.pow(Pth,2/3))*(p.v/v0);else rrs=Cp*p.P*1000*p.v;
  const rr=rrs*60*1e9;const notes=[];if(p.model==='zs'&&p.P<=Pth)notes.push('Below the threshold pressure (7 kPa assumed): no removal in the Zhao–Shi model.');
  if(p.mat==='cu'&&p.P>21)notes.push('High pressure on copper with low-k dielectrics risks delamination; modern Cu CMP uses about 1–2 psi.');
  if(p.P<10)notes.push('Very low pressure: pad contact becomes uneven and Preston behaviour breaks down.');
  return {o:{rr,tclr:p.h/rr*60,psi:p.P/6.895,Cp:Cp*1e13},notes};},
 theory:{principle:['The wafer is held face-down in a carrier and pressed against a rotating polyurethane pad wetted with slurry. Both carrier and platen rotate so every point on the wafer sees nearly the same relative velocity.',
  'Slurry chemistry (pH, oxidisers, complexing agents) converts the surface into a softer layer, and the nanometre abrasive with pad asperities removes that layer. Neither chemistry nor abrasion alone gives the same rate or planarity.',
  'CMP is essential in semiconductor manufacturing to planarise oxide between metal layers, to form copper interconnects (damascene) and tungsten plugs, and to polish bare silicon wafers.'],
  eq:[{f:'MRR = <var>C</var><sub>p</sub> · <var>P</var> · <var>v</var>',w:'Preston\'s equation for blanket films.'},
   {f:'<var>t</var><sub>clear</sub> = <var>h</var> / MRR',w:'Polishing time to remove a film of thickness h.'}],
  effects:['Removal rate is close to linear in pressure and velocity for blanket films.','Chemistry sets the Preston coefficient: copper polishes much faster than oxide.','Over-polishing causes dishing of wide copper lines and erosion of dense arrays.','Pad conditioning keeps the rate stable.'],
  apps:['Inter-layer dielectric planarisation','Copper damascene interconnects','Tungsten plug formation','Bare silicon wafer and hard-disk substrate polishing'],
  adv:['Global planarity at the nanometre level','Enables multilayer interconnects','Low defectivity with optimised slurry'],
  lim:['Dishing, erosion and scratches','Slurry and pad consumables are costly','Process sensitive to pattern density and pad condition'],
  model:'<b>Simulator model.</b> Preston\'s law with C_p chosen to give typical blanket rates: oxide ≈ 200 nm/min at 34 kPa (5 psi) and 1 m/s; copper ≈ 500 nm/min at about 2 psi; tungsten ≈ 300 nm/min at 5 psi. Pattern-density effects are not modelled. Indicative, not validated.'},
 procedure:['Select oxide, 1 m/s.','Vary pressure from 7 to 55 kPa; confirm the rate is linear in pressure.','At 34 kPa, vary velocity and confirm linearity.','Compare time to clear 500 nm for oxide, copper and tungsten.'],
 quiz:[{q:'CMP combines…',o:['Laser heating and grinding','Chemical softening and mechanical abrasion','Sparks and electrolysis','Ultrasonics and magnets'],a:1,why:'Both actions are needed for its rate and planarity.'},
  {q:'By Preston\'s law, doubling down pressure in CMP makes the removal rate…',o:['Halve','Double','Unchanged','Quadruple'],a:1,why:'MRR = C_p·P·v.'},
  {q:'Over-polishing wide copper lines causes…',o:['Dishing','Cracking of silicon','Oxidation only','Thicker lines'],a:0,why:'Soft copper is removed below the surrounding dielectric.'},
  {q:'CMP is critical in semiconductor fabrication for…',o:['Doping','Global planarisation of layers','Lithography exposure','Packaging'],a:1,why:'Each interconnect level must be flat for the next lithography step.'}]},
/* ======================= IBM ======================= */
{id:'ibm',abbr:'IBM',name:'Ion Beam Machining',cat:'nano',
 blurb:'Argon ions accelerated in vacuum knock atoms off the surface one by one (sputtering).',
 facts:{energy:'Kinetic energy of ions (0.2–2 keV)',mech:'Physical sputtering: momentum transfer ejects surface atoms',medium:'High vacuum (≈10⁻⁴ torr), argon ions',tool:'Broad-beam ion source with extraction grids'},
 aim:'To study how ion energy, current density and incidence angle set the sputter yield and removal rate in ion beam machining.',
 params:[
  {id:'E',label:'Ion energy',unit:'eV',min:200,max:2000,step:50,val:1000},
  {id:'J',label:'Ion current density',unit:'mA/cm²',min:0.1,max:2,step:0.05,val:1},
  {id:'th',label:'Incidence angle (from normal)',unit:'°',min:0,max:80,step:1,val:0},
  {id:'t',label:'Milling time',unit:'min',min:1,max:60,step:1,val:10},
  {id:'mat',label:'Target material',type:'select',val:'cu',options:[['si','Silicon'],['ti','Titanium'],['fe','Iron'],['cu','Copper'],['au','Gold'],['w','Tungsten']]},
 ],
 mats:{si:{Y:0.53,M:28.09,rho:2.33},ti:{Y:0.58,M:47.87,rho:4.51},fe:{Y:1.26,M:55.85,rho:7.87},cu:{Y:2.30,M:63.55,rho:8.96},au:{Y:2.8,M:196.97,rho:19.3},w:{Y:0.62,M:183.84,rho:19.3}},
 outputs:[{k:'rr',label:'Removal rate',unit:'nm/min',pri:1},{k:'Y',label:'Sputter yield',unit:'atoms/ion'},{k:'h',label:'Depth milled',unit:'nm'},{k:'flux',label:'Ion flux',unit:'×10¹⁵ ions/cm²·s'}],
 sweep:{x:'th',y:'rr'},
 compute(p){const m=this.mats[p.mat];const fa=p.th<=60?1/Math.cos(p.th*Math.PI/180):2*(90-p.th)/30;const Y=m.Y*Math.sqrt(p.E/600)*fa;
  const Jm=p.J*10;const v=Jm*Y*(m.M/1000)/(1.602e-19*6.022e23*m.rho*1000);const rr=v*60*1e9;const notes=[];
  if(p.th>60)notes.push('Beyond about 60° ions glance off the surface and the yield falls quickly.');if(p.E<300)notes.push('Low energy: close to the sputtering threshold, yield is small and the square-root scaling is less accurate.');
  return {o:{rr,Y,h:rr*p.t,flux:Jm/1.602e-19/1e4/1e15},notes};},
 theory:{principle:['Argon is ionised in a discharge chamber, and the ions are extracted and accelerated by grids to a few hundred to a few thousand electron-volts. A neutraliser adds electrons so the beam does not charge insulating targets.',
  'When an energetic ion strikes the surface, it sets off a collision cascade; atoms near the surface receive enough momentum to escape. The average number of atoms ejected per ion is the sputter yield.',
  'Removal is atom by atom, so IBM is used for the most precise finishing and figuring: thinning specimens for electron microscopy, final figuring of optics, and patterning thin films through masks.'],
  eq:[{f:'<var>v</var> = <var>J</var>·<var>Y</var>·<var>M</var> / (<var>e</var>·<var>N</var><sub>A</sub>·ρ)',w:'Removal velocity from current density J, yield Y (atoms/ion), molar mass M and density ρ.'},
   {f:'<var>Y</var>(<var>E</var>,θ) ≈ <var>Y</var><sub>600</sub>·√(<var>E</var>/600)·(1/cos θ)',w:'Approximate scaling with energy and incidence angle up to ~60°.'}],
  effects:['Removal rate is proportional to ion current density.','Yield rises roughly as the square root of energy in this range.','Tilting the beam raises the yield up to about 60°, then it falls.','Materials differ greatly: Cu and Au sputter much faster than Si or W.'],
  apps:['TEM specimen thinning','Final figuring of precision optics','Patterning of thin-film devices (ion milling)','Surface cleaning and texturing'],
  adv:['Atomic-scale removal and no mechanical stress','Works on any material, including insulators','Highly directional and precise'],
  lim:['Very slow (nm/min)','Vacuum equipment needed','Redeposition and surface damage from ion implantation'],
  model:'<b>Simulator model.</b> Exact removal-velocity formula with approximate Ar⁺ sputter yields at 600 eV (Si 0.53, Ti 0.58, Fe 1.26, Cu 2.3, Au 2.8, W 0.62), scaled by √(E/600) and 1/cos θ up to 60°. The yields are approximate values from published sputter-yield tables; check against current tables before quantitative use.'},
 procedure:['Select copper, 1 keV, 1 mA/cm², normal incidence.','Vary incidence angle from 0 to 80°; plot removal rate vs angle.','Vary energy from 200 to 2000 eV at normal incidence.','Compare silicon, copper and tungsten at the same settings.'],
 quiz:[{q:'IBM removes material by…',o:['Melting','Sputtering: atoms knocked out by ion impacts','Chemical dissolution','Abrasion'],a:1,why:'Momentum transfer in collision cascades ejects surface atoms.'},
  {q:'Sputter yield is defined as…',o:['Ions per atom','Atoms ejected per incident ion','Current per area','Energy per atom'],a:1,why:'It is the average number of target atoms removed per ion.'},
  {q:'A neutraliser is used in IBM to…',o:['Cool the target','Prevent charge build-up on insulating targets','Increase ion energy','Pump the vacuum'],a:1,why:'Electrons added to the beam neutralise its charge.'},
  {q:'Tilting the beam from normal to about 60° generally…',o:['Lowers yield','Raises yield','Stops sputtering','Has no effect'],a:1,why:'The cascade is closer to the surface, so more atoms escape.'}]}
);
// update reference list of described-only processes
OTHERS.length=0;
OTHERS.push(
 {abbr:'MRAFF',name:'Magnetorheological Abrasive Flow Finishing',cat:'nano',t:'Combines AFM and MRF: MR fluid with abrasive is extruded through a passage while a magnetic field controls its stiffness, giving nanometre finishes on internal surfaces.'},
 {abbr:'EEM',name:'Elastic Emission Machining',cat:'nano',t:'Ultrafine powder particles carried by fluid flow are brought to the surface and remove atoms by chemical bonding, producing atomically smooth, damage-free surfaces.'},
 {abbr:'UAEDM',name:'Ultrasonic-Assisted EDM',cat:'hyb',t:'Ultrasonic vibration of the electrode or work improves flushing in EDM, raising MRR and stability in micro-holes and deep cavities.'},
 {abbr:'PCM',name:'Photochemical Machining',cat:'chem',t:'A photoresist mask exposed through a phototool defines the pattern, then spray etching removes metal. Used for shims, meshes, encoder discs and lead frames.'},
 {abbr:'STEM',name:'Shaped Tube Electrolytic Machining',cat:'chem',t:'An insulated titanium tube cathode with acid electrolyte drills deep small holes (aspect ratio up to 300:1) in turbine blades.'},
 {abbr:'EDG',name:'Electrical Discharge Grinding',cat:'hyb',t:'A rotating graphite or metal wheel removes material by sparking, without abrasive contact. Used for PCD tools and carbide form tools.'},
 {abbr:'ECH',name:'Electrochemical Honing',cat:'hyb',t:'Honing stones and electrolytic dissolution act together to finish bores faster than honing alone, with no stress or heat damage.'},
);

// ---- validation status for new processes
Object.assign(VALID,{
 ecg:{status:'none',summary:'Not yet validated. Faraday dissolution is exact; needed: MRR and current for a stated wheel, gap and material.'},
 ecdm:{status:'none',summary:'Not yet validated. Needed: depth vs time and critical voltage for glass at known NaOH concentration and tool diameter.'},
 rum:{status:'none',summary:'Not yet validated. MRR is exact for a core drill; needed: axial force vs feed with and without vibration.'},
 lam:{status:'none',summary:'Not yet validated. Needed: measured cutting-zone temperature and cutting force vs laser power.'},
 afm:{status:'none',summary:'Not yet validated. Needed: Ra vs number of cycles at known pressure, concentration and grit.'},
 maf:{status:'none',summary:'Magnetic pressure uses the standard Shinmura expression. Finishing rate is not yet validated; needed: Ra vs time at known flux density and speed.'},
 mrf:{status:'none',summary:'Not yet validated. Needed: removal rate vs wheel speed and field for a stated MR fluid and material.'},
 cmp:{status:'none',summary:'Not yet validated. Preston coefficients chosen to match typical blanket rates; needed: rate vs pressure for a stated pad and slurry.'},
 ibm:{status:'none',summary:'Not yet validated. The removal-velocity formula is exact; the sputter yields are approximate published values at 600 eV.'},
});
