Object.assign(PRE,{
 ecg:[{q:'In electrolysis, metal dissolves at the…',o:['Cathode','Anode','Both','Neither'],a:1,why:'Oxidation occurs at the anode.'},{q:'A passive film on a metal surface…',o:['Speeds dissolution','Slows further dissolution','Conducts better','Is always magnetic'],a:1,why:'It insulates and blocks the reaction.'},{q:'Grinding wheels used in ECG must be…',o:['Vitrified (non-conductive)','Electrically conductive (metal-bonded)','Rubber-bonded','Wooden'],a:1,why:'The wheel is the cathode.'}],
 ecdm:[{q:'At the cathode during electrolysis of water, the gas evolved is…',o:['Oxygen','Hydrogen','Chlorine','Nitrogen'],a:1,why:'Water is reduced to H₂ at the cathode.'},{q:'Glass is…',o:['A good electrical conductor','An electrical insulator','A metal','A semiconductor'],a:1,why:'That is why EDM and ECM cannot machine it.'},{q:'A gas film in a strong electric field can…',o:['Never conduct','Break down and allow discharges','Become magnetic','Freeze'],a:1,why:'Dielectric breakdown occurs above a critical field.'}],
 rum:[{q:'Diamond core drills remove…',o:['A solid cylinder','An annulus, leaving a core','Only the surface layer','Nothing'],a:1,why:'The hollow tool cuts a ring.'},{q:'Ultrasonic frequency is about…',o:['50 Hz','20 kHz','2 GHz','1 Hz'],a:1,why:'Just above human hearing.'},{q:'Edge chipping in brittle materials grows with…',o:['Lower cutting force','Higher cutting force','Coolant use','Sharper tools'],a:1,why:'Higher forces drive larger exit cracks.'}],
 lam:[{q:'Most metals\' strength as temperature rises…',o:['Increases','Decreases','Stays constant','Becomes zero at 100 °C'],a:1,why:'Thermal softening reduces flow stress.'},{q:'A material with low thermal conductivity…',o:['Spreads heat quickly','Keeps heat concentrated near the surface','Cannot be heated','Reflects lasers'],a:1,why:'Heat diffuses slowly away.'},{q:'Specific cutting energy is the energy needed per unit…',o:['Time','Volume of material removed','Length of tool','Mass of chip only'],a:1,why:'Units J/mm³ (= N/mm²).'}],
 afm:[{q:'A viscoelastic material behaves…',o:['Only like a liquid','Partly like a liquid and partly like a solid','Only like a solid','Like a gas'],a:1,why:'It flows yet resists rapid deformation elastically.'},{q:'Ra measures…',o:['Hardness','Average surface roughness','Grain size','Flatness of a plane'],a:1,why:'Arithmetic mean deviation of the profile.'},{q:'A burr is…',o:['A crack','A raised edge left by machining','A coating','A hole'],a:1,why:'Unwanted material at an edge.'}],
 maf:[{q:'Iron particles in a magnetic field tend to…',o:['Repel and scatter','Form chains along field lines','Melt','Become non-magnetic'],a:1,why:'They magnetise and attract one another along the field.'},{q:'Magnetic pressure scales with flux density as…',o:['B','B²','1/B','√B'],a:1,why:'Magnetic energy density is B²/2μ₀.'},{q:'μ₀ (permeability of free space) is…',o:['4π×10⁻⁷ H/m','9.81 m/s²','8.85×10⁻¹² F/m','1.6×10⁻¹⁹ C'],a:0,why:'Used in magnetic pressure calculations.'}],
 mrf:[{q:'Viscosity describes a fluid\'s…',o:['Density','Resistance to flow','Colour','Conductivity'],a:1,why:'High viscosity means it flows less easily.'},{q:'A smart fluid whose viscosity changes with magnetic field is called…',o:['Newtonian','Magnetorheological','Electrolyte','Dielectric'],a:1,why:'MR fluids stiffen in a field.'},{q:'Polishing removal rate generally rises with…',o:['Lower pressure','Higher pressure and speed','Lower speed','Colder slurry only'],a:1,why:'Preston\'s law.'}],
 cmp:[{q:'Planarisation means making a surface…',o:['Rough','Flat across the wafer','Curved','Thicker'],a:1,why:'Needed for later lithography steps.'},{q:'1 psi is approximately…',o:['6.9 kPa','69 kPa','0.69 kPa','690 kPa'],a:0,why:'1 psi ≈ 6.895 kPa.'},{q:'Colloidal silica abrasive particles are typically…',o:['Millimetres','Tens of nanometres','Hundreds of microns','Centimetres'],a:1,why:'Nano-abrasives give scratch-free polishing.'}],
 ibm:[{q:'An Ar⁺ ion accelerated through 1000 V gains energy…',o:['1 eV','1000 eV (1 keV)','1 MeV','1 J'],a:1,why:'E = qV for a singly charged ion.'},{q:'Avogadro\'s number is about…',o:['6.02×10²³ /mol','9.65×10⁴ /mol','1.6×10⁻¹⁹','3×10⁸'],a:0,why:'Converts atoms to moles.'},{q:'IBM requires vacuum mainly so that…',o:['The target cools','Ions are not scattered by gas molecules','Argon is pumped away','The beam becomes visible'],a:1,why:'Ions need a long mean free path.'}],
});
// ---- numericals
Object.assign(NUM,{
 ecg:()=>{const I=rr(200,1500,50);const ans=0.9*I*55.85/(2*96485*7.86)*60*1000/0.9;return {q:`ECG of tool steel (Fe, M = 55.85, z = 2, ρ = 7.86 g/cm³) runs at ${I} A with 90 % current efficiency. If 90 % of removal is electrolytic and 10 % mechanical, find total MRR.`,unit:'mm³/min',ans,sol:`MRR_e = 0.9 × ${I} × 55.85/(2 × 96485 × 7.86) cm³/s × 60 000 = ${(ans*0.9).toFixed(0)} mm³/min. Total = MRR_e/0.9 = ${ans.toFixed(0)} mm³/min.`};},
 ecdm:()=>{const r0=rr(4,12,0.5),h0=rr(150,350,10),t=rr(20,180,10);const ans=h0*Math.log(1+r0*t/h0);return {q:`In ECDM drilling, the depth law is h = h₀·ln(1 + r₀t/h₀) with r₀ = ${r0} µm/s and h₀ = ${h0} µm. Find the depth after ${t} s.`,unit:'µm',ans,sol:`h = ${h0} × ln(1 + ${r0}×${t}/${h0}) = ${h0} × ln(${(1+r0*t/h0).toFixed(3)}) = ${ans.toFixed(1)} µm.`};},
 rum:()=>{const D=rr(6,16,1),w=rr(0.8,2,0.1),f=rr(0.5,4,0.1);const ans=f*Math.PI/4*(D*D-Math.pow(D-2*w,2));return {q:`A RUM core drill has outer diameter ${D} mm and wall thickness ${w.toFixed(1)} mm. At a feed of ${f.toFixed(1)} mm/min, find the MRR.`,unit:'mm³/min',ans,sol:`d_i = ${D} − 2×${w.toFixed(1)} = ${(D-2*w).toFixed(1)} mm. MRR = f·π/4·(D² − d_i²) = ${f.toFixed(1)} × π/4 × (${D*D} − ${(Math.pow(D-2*w,2)).toFixed(2)}) = ${ans.toFixed(1)} mm³/min.`};},
 lam:()=>{const u0=pick([4,4.5,5]),Ts=rr(0.2,0.5,0.05),m=pick([0.8,1,1.3]),f=rr(0.05,0.25,0.01),ap=rr(0.3,1.5,0.1);const u=u0*(1-Math.pow(Ts,m));const ans=u*1000*f*ap;return {q:`In laser-assisted turning, u₀ = ${u0} J/mm³ and softening follows u = u₀(1 − T*^m) with m = ${m}. At homologous temperature T* = ${Ts.toFixed(2)}, feed ${f.toFixed(2)} mm/rev and depth ${ap.toFixed(1)} mm, find the cutting force.`,unit:'N',ans,sol:`u = ${u0} × (1 − ${Ts.toFixed(2)}^${m}) = ${u.toFixed(3)} J/mm³ = ${(u*1000).toFixed(0)} N/mm². F = u·f·a_p = ${(u*1000).toFixed(0)} × ${f.toFixed(2)} × ${ap.toFixed(1)} = ${ans.toFixed(1)} N.`};},
 afm:()=>{const R0=rr(1,4,0.1),Rm=rr(0.1,0.4,0.05),n0=rr(10,40,1),n=rr(5,60,1);const ans=Rm+(R0-Rm)*Math.exp(-n/n0);return {q:`In AFM, Ra falls as Ra = Ra_min + (Ra₀ − Ra_min)·e^(−n/n₀). With Ra₀ = ${R0.toFixed(1)} µm, Ra_min = ${Rm.toFixed(2)} µm and n₀ = ${n0}, find Ra after ${n} cycles.`,unit:'µm',ans,sol:`Ra = ${Rm.toFixed(2)} + (${R0.toFixed(1)} − ${Rm.toFixed(2)}) × e^(−${n}/${n0}) = ${ans.toFixed(3)} µm.`};},
 maf:()=>{const B=rr(0.2,1.0,0.05),mu=rr(2,5,0.5);const ans=B*B/(2*MU0)*(1-1/mu)/1000;return {q:`Find the magnetic finishing pressure in MAF for flux density ${B.toFixed(2)} T and brush relative permeability ${mu}.`,unit:'kPa',ans,sol:`P = B²/(2μ₀)·(1 − 1/μ_r) = ${(B*B).toFixed(4)}/(2 × 4π×10⁻⁷) × ${(1-1/mu).toFixed(3)} = ${ans.toFixed(1)} kPa.`};},
 mrf:()=>{const Cp=pick([2,2.5,5]),P=rr(10,40,1),v=rr(0.5,3,0.1);const ans=Cp*1e-13*P*1000*v*60*1e6;return {q:`Using Preston's law with C_p = ${Cp}×10⁻¹³ m²/N, pressure ${P} kPa and velocity ${v.toFixed(1)} m/s, find the MRF removal rate.`,unit:'µm/min',ans,sol:`dh/dt = C_p·P·v = ${Cp}×10⁻¹³ × ${P*1000} × ${v.toFixed(1)} = ${(ans/60e6).toExponential(3)} m/s = ${ans.toFixed(3)} µm/min.`};},
 cmp:()=>{const psi=rr(1,7,0.5),v=rr(0.5,1.5,0.1),Cp=pick([1,1.5,6]),h=rr(200,1500,50);const P=psi*6.895;const rrv=Cp*1e-13*P*1000*v*60*1e9;const ans=h/rrv*60;return {q:`A CMP step must remove ${h} nm of film. Pressure ${psi} psi, relative velocity ${v.toFixed(1)} m/s, C_p = ${Cp}×10⁻¹³ m²/N. How long will it take?`,unit:'s',ans,sol:`P = ${psi} × 6.895 = ${P.toFixed(2)} kPa. MRR = C_p·P·v = ${rrv.toFixed(1)} nm/min. t = ${h}/${rrv.toFixed(1)} min = ${ans.toFixed(1)} s.`};},
 ibm:()=>{const m=pick([['copper',63.55,8.96],['silicon',28.09,2.33],['iron',55.85,7.87]]),J=rr(0.2,2,0.1),Y=rr(0.5,3,0.1);const v=J*10*Y*(m[1]/1000)/(1.602e-19*6.022e23*m[2]*1000);const ans=v*60*1e9;return {q:`Ion milling of ${m[0]} (M = ${m[1]} g/mol, ρ = ${m[2]} g/cm³) at ${J.toFixed(1)} mA/cm² with sputter yield ${Y.toFixed(1)} atoms/ion. Find the removal rate.`,unit:'nm/min',ans,sol:`v = J·Y·M/(e·N_A·ρ) = ${J*10} A/m² × ${Y.toFixed(1)} × ${m[1]/1000} / (1.602×10⁻¹⁹ × 6.022×10²³ × ${m[2]*1000}) = ${v.toExponential(3)} m/s = ${ans.toFixed(1)} nm/min.`};},
});
